import Link from 'next/link';
import { Building2, PackageSearch, ShieldCheck, Store } from 'lucide-react';

import { getAdminAccess } from '@/features/admin/auth/adminPermissions';
import { AdminMetric, AdminPage, AdminPageHeader, AdminPanel, adminFieldClass } from '@/features/admin/components';
import { MediaChoiceGrid } from '@/features/admin/media';
import { createVendor, setVendorStatus } from '@/features/admin/vendors/actions';
import { prisma } from '@/lib/prisma';

export default async function AdminVendorsPage(){const access=await getAdminAccess();if(!access.permissions.has('vendor:view'))throw new Error('Vendor management access is required.');const [vendors,media]=await Promise.all([prisma.vendorProfile.findMany({where:{workspaceId:access.membership.workspaceId,status:{not:'ARCHIVED'}},include:{ownerUser:{select:{name:true,email:true}},logoMediaAsset:{select:{secureUrl:true}},_count:{select:{products:true,promotions:true,collections:true,campaigns:true,members:true}}},orderBy:[{active:'desc'},{updatedAt:'desc'}]}),prisma.mediaAsset.findMany({where:{workspaceId:access.membership.workspaceId,status:'ACTIVE',resourceType:'IMAGE'},orderBy:{createdAt:'desc'},take:150})]);const active=vendors.filter(v=>v.status==='ACTIVE').length;const pending=vendors.filter(v=>v.status==='PENDING').length;const totalProducts=vendors.reduce((sum,v)=>sum+v._count.products,0);const enabled=access.membership.workspace.commerceMode==='MULTI_VENDOR';return <AdminPage><div className="mx-auto max-w-[96rem] space-y-5"><AdminPageHeader eyebrow="Marketplace control" title="Vendors Management" description="Manage vendor profiles, teams, ownership and approvals. Only Developer Admin can activate the Multi Vendor capability."/><section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><AdminMetric icon={Store} label="Vendors" value={vendors.length}/><AdminMetric icon={ShieldCheck} label="Active" value={active}/><AdminMetric icon={Building2} label="Pending" value={pending}/><AdminMetric icon={PackageSearch} label="Vendor products" value={totalProducts}/></section>{!enabled?<div className="rounded-[2rem] border border-amber-500/30 bg-amber-500/10 p-6 text-sm text-amber-700"><strong>Single Merchant mode is active.</strong><p className="mt-2 text-xs leading-5">Vendor data is preserved, but onboarding and Vendor Studio access remain blocked until Developer Admin activates Multi Vendor mode.</p></div>:null}{enabled&&access.permissions.has('vendor:manage')?<AdminPanel title="Create or onboard vendor" description="The owner must already have a normal Shelsea account."><form action={createVendor} className="grid gap-4 lg:grid-cols-3"><Field label="Vendor name"><input name="name" required className={adminFieldClass}/></Field><Field label="Slug"><input name="slug" className={adminFieldClass}/></Field><Field label="Owner account email"><input name="ownerEmail" type="email" required className={adminFieldClass}/></Field><Field label="Public email"><input name="email" type="email" className={adminFieldClass}/></Field><Field label="Phone"><input name="phone" className={adminFieldClass}/></Field><Field label="Description"><input name="description" className={adminFieldClass}/></Field><fieldset className="lg:col-span-3"><legend className="mb-2 text-[9px] font-bold uppercase tracking-[0.14em] text-muted-foreground">Logo gallery</legend><MediaChoiceGrid media={media} name="logoMediaAssetId" emptyLabel="No logo" purpose="general" uploadAccept="image" acceptedResourceTypes={['IMAGE']} /></fieldset><button className="h-12 rounded-full bg-foreground px-5 text-sm font-bold text-background lg:col-span-3">Create vendor profile</button></form></AdminPanel>:null}<section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{vendors.map(vendor=><article key={vendor.id} className="rounded-[2rem] border border-border/60 bg-card/75 p-5 shadow-sm"><div className="flex items-start justify-between gap-3">{vendor.logoMediaAsset?/* eslint-disable-next-line @next/next/no-img-element */<img src={vendor.logoMediaAsset.secureUrl} alt="" className="size-12 rounded-2xl object-cover"/>:<span className="grid size-12 place-items-center rounded-2xl bg-muted"><Store className="size-5"/></span>}<span className={vendor.status==='ACTIVE'?'rounded-full bg-emerald-500/10 px-2 py-1 text-[8px] font-bold text-emerald-600':'rounded-full bg-amber-500/10 px-2 py-1 text-[8px] font-bold text-amber-600'}>{vendor.status}</span></div><h2 className="mt-4 text-lg font-black">{vendor.name}</h2><p className="mt-1 text-[10px] text-muted-foreground">Owner: {vendor.ownerUser.name} · {vendor.ownerUser.email}</p><div className="mt-4 grid grid-cols-4 gap-1 rounded-2xl bg-muted/40 p-3 text-center"><Small label="Products" value={vendor._count.products}/><Small label="Offers" value={vendor._count.promotions}/><Small label="Collections" value={vendor._count.collections}/><Small label="Team" value={vendor._count.members}/></div><div className="mt-4 flex flex-wrap gap-2"><Link href={`/admin/vendors/${vendor.id}`} className="rounded-full bg-foreground px-3 py-2 text-[9px] font-bold text-background">Manage</Link>{access.permissions.has('vendor:approve')? <>{vendor.status!=='ACTIVE'&&enabled?<Status id={vendor.id} status="ACTIVE" label="Approve"/>:null}{vendor.status==='ACTIVE'?<Status id={vendor.id} status="SUSPENDED" label="Suspend" secondary/>:null}{vendor.status==='PENDING'?<Status id={vendor.id} status="REJECTED" label="Reject" secondary/>:null}</>:null}</div></article>)}</section></div></AdminPage>}
function Field({label,children}:{label:string;children:React.ReactNode}){return <label><span className="mb-2 block text-[9px] font-bold uppercase tracking-[.14em] text-muted-foreground">{label}</span>{children}</label>}
function Small({label,value}:{label:string;value:number}){return <div><p className="text-sm font-black">{value}</p><p className="mt-1 text-[7px] text-muted-foreground">{label}</p></div>}
function Status({id,status,label,secondary=false}:{id:string;status:string;label:string;secondary?:boolean}){return <form action={setVendorStatus}><input type="hidden" name="id" value={id}/><input type="hidden" name="status" value={status}/><button className={secondary?'rounded-full border border-border px-3 py-2 text-[9px] font-bold':'rounded-full bg-foreground px-3 py-2 text-[9px] font-bold text-background'}>{label}</button></form>}
